 "A save is still going. Leaving now could lose it.": "Es wird noch gespeichert. Wenn du jetzt gehst, kann es verloren gehen.",
 "A section you add starts on this scheme.": "Ein neuer Abschnitt startet mit diesem Schema.",
 "A segment": "Ein Segment",
 "A shipping profile is a group of products that ship the same way. Every product starts in the General profile.": "Ein Versandprofil ist eine Gruppe von Produkten, die gleich versendet werden. Jedes Produkt startet im Profil Allgemein.",
 "A shipping rate for where you sell, or local pickup.": "Ein Versandtarif für deine Verkaufsgebiete oder lokale Abholung.",
 "A short bio about yourself...": "Eine kurze Bio über dich...",
 "A space name is up to {max} characters.": "Ein Bereichsname hat höchstens {max} Zeichen.",
 "A store can have up to {maxMarkets} markets.": "Ein Shop kann bis zu {maxMarkets} Märkte haben.",
 "A store holds {menus} menus.": "Ein Shop fasst {menus} Menüs.",
 "A supplier or manufacturer": "Ein Lieferant oder Hersteller",
 "A supplier ships straight to your buyers.": "Ein Lieferant versendet direkt an deine Käufer.",
 "A supplier's catalogue, shipped by the supplier.": "Der Katalog eines Lieferanten, vom Lieferanten verschickt.",
 "A ticket is at least 0.50.": "Ein Ticket kostet mindestens 0,50.",
 "A title between your links": "Ein Titel zwischen deinen Links",
 "A title is up to {max} characters.": "Ein Titel hat höchstens {max} Zeichen.",
 "A video here is at most {maxVideo}": "Ein Video hier hat höchstens {maxVideo}",
 "A video, playing on a loop": "Ein Video in Schleife",
 "A visitor confirms their review from an email before it posts, and it is not marked Verified buyer or counted in your Storelib rating. A buyer who uses the form is sent their own link instead.": "Ein Besucher bestätigt seine Bewertung per E-Mail, bevor sie erscheint; sie wird nicht als Verifizierter Käufer markiert und zählt nicht zu deinem Storelib-Rating. Käufer, die das Formular nutzen, bekommen stattdessen ihren eigenen Link.",
 "A wait at the end does nothing. Add an email after it, or remove it.": "Eine Wartezeit am Ende bewirkt nichts. Füg danach eine E-Mail hinzu oder entferne sie.",
 "A wait can be up to {maxWaitDays} days.": "Eine Wartezeit darf bis zu {maxWaitDays} Tage dauern.",
