 "At checkout Storelib looks at where the buyer is and adds that region's rate. Buyers anywhere else pay no tax.": "Im Checkout schaut Storelib, wo der Käufer ist, und addiert den Satz dieser Region. Käufer anderswo zahlen keine Steuer.",
