 "Buy Now": "Jetzt kaufen",
 "Buy a label": "Ein Label kaufen",
 "Buy and print labels from the order page at EasyPost's rates. The tracking number goes on the shipment.": "Kauf und druck Labels auf der Bestellseite zu EasyPost-Tarifen. Die Sendungsnummer kommt an die Sendung.",
 "Buy and print labels from the order page at Shippo's rates. The tracking number goes on the shipment.": "Kauf und druck Labels auf der Bestellseite zu Shippo-Tarifen. Die Sendungsnummer kommt an die Sendung.",
 "Buy for {priceLabel}": "Für {priceLabel} kaufen",
 "Buy it together": "Zusammen kaufen",
 "Buy label · {price}": "Label kaufen · {price}",
 "Buy now and the cart open Storelib checkout. A cart with something to post asks for the address and delivery first.": "„Jetzt kaufen“ und der Warenkorb öffnen den Storelib-Checkout. Ein Warenkorb mit Versandartikeln fragt zuerst Adresse und Lieferung ab.",
 "Buy opens Storelib checkout. Cards and Google Pay, through Stripe.": "„Kaufen“ öffnet den Storelib-Checkout. Karten und Google Pay, über Stripe.",
 "Buy {title}": "{title} kaufen",
 "Buyer cases": "Käuferfälle",
 "Buyers add it for {amount}, instead of {amount2}.": "Käufer fügen es für {amount} statt {amount2} hinzu.",
 "Buyers add it for {amount}.": "Käufer fügen es für {amount} hinzu.",
 "Buyers are asked by email after they buy, on your schedule in Storelib Reviews.": "Käufer werden nach dem Kauf per E-Mail gefragt, nach deinem Zeitplan in Storelib Reviews.",
 "Buyers ask for a return from their order page, and you approve each one.": "Käufer beantragen eine Rücksendung auf ihrer Bestellseite, und du gibst jede frei.",
 "Buyers can add up to 4 photos. Each one is checked before it is kept.": "Käufer können bis zu 4 Fotos hinzufügen. Jedes wird vor dem Speichern geprüft.",
 "Buyers can change their review for": "Käufer können ihre Bewertung ändern für",
 "Buyers can choose it": "Käufer können sie wählen",
 "Buyers can collect their order here for free instead of having it shipped.": "Käufer können ihre Bestellung hier kostenlos abholen, statt sie liefern zu lassen.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now instead, turn it off.": "Käufer können ihn nicht mehr nutzen. Bestellungen mit diesem Code behalten ihren Rabatt. Um ihn vorerst zu stoppen, schalte ihn stattdessen aus.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now, turn it off instead.": "Käufer können ihn nicht mehr nutzen. Bestellungen, die ihn schon verwendet haben, behalten ihren Rabatt. Um ihn vorerst zu stoppen, schalte ihn stattdessen aus.",
 "Buyers can still order, and you ship when it's back.": "Käufer können trotzdem bestellen, und du versendest, sobald es wieder da ist.",
 "Buyers can use it at checkout.": "Käufer können ihn beim Checkout nutzen.",
 "Buyers can't check out a physical product until it has a rate for their address. Add a zone and a rate below.": "Käufer können ein physisches Produkt erst bezahlen, wenn es einen Tarif für ihre Adresse gibt. Füg unten eine Zone und einen Tarif hinzu.",
 "Buyers can't check out on your store yet": "Käufer können in deinem Shop noch nicht bezahlen",
 "Buyers can't check out until you do.": "Käufer können erst danach bezahlen.",
 "Buyers can't check out yet": "Käufer können noch nicht bezahlen",
 "Buyers can't check out your physical products yet": "Käufer können deine physischen Produkte noch nicht bezahlen",
 "Buyers can't pay at checkout until this is done.": "Käufer können im Checkout erst bezahlen, wenn das erledigt ist.",
 "Buyers can't pay for anything until this is done.": "Käufer können nichts bezahlen, bis das erledigt ist.",
 "Buyers choose the price": "Käufer wählen den Preis",
 "Buyers choose what to pay, from your minimum.": "Käufer wählen den Betrag, ab deinem Minimum.",
 "Buyers create an account or log in before checkout. Signed out visitors can still browse.": "Käufer erstellen ein Konto oder melden sich vor dem Checkout an. Nicht angemeldete Besucher können weiter stöbern.",
 "Buyers keep their files and their access.": "Käufer behalten ihre Dateien und ihren Zugang.",
 "Buyers never see it": "Käufer sehen das nie",
 "Buyers only": "Nur Käufer",
 "Buyers only see it struck through when it is higher than the price.": "Käufer sehen ihn nur durchgestrichen, wenn er höher als der Preis ist.",
 "Buyers reply to order emails. Right now replies go to your login email.": "Käufer antworten auf Bestell-E-Mails. Im Moment gehen Antworten an deine Anmelde-E-Mail.",
 "Buyers review from their receipt or their library. Storelib asks them a week after they buy on Storelib, and again a week later if they have not.": "Käufer bewerten über ihren Beleg oder ihre Bibliothek. Storelib fragt eine Woche nach dem Kauf auf Storelib und noch einmal eine Woche später, falls sie es nicht getan haben.",
 "Buyers see it as sold out. Add stock, or let it keep selling when it runs out.": "Käufer sehen es ausverkauft. Füg Bestand hinzu oder lass es weiterverkaufen, wenn es leer ist.",
 "Buyers see it when they choose pickup": "Käufer sehen es, wenn sie Abholung wählen",
 "Buyers see them as sold out. Add stock, or let them keep selling when they run out.": "Käufer sehen sie ausverkauft. Füg Bestand hinzu oder lass sie weiterverkaufen, wenn sie leer sind.",
 "Buyers see these words on the event page and in their receipt.": "Käufer sehen diesen Text auf der Event-Seite und in ihrem Beleg.",
 "Buyers see “Name a fair price”, starting at your suggested amount.": "Käufer sehen „Nenne einen fairen Preis“, beginnend bei deinem Vorschlag.",
 "Buyers watch these in their library, and pick up where they left off.": "Käufer sehen sie in ihrer Bibliothek und machen dort weiter, wo sie aufgehört haben.",
 "Buyers who asked to hear from you when they paid.": "Käufer, die beim Bezahlen um Neuigkeiten von dir gebeten haben.",
 "Buyers who choose pickup aren't told when they can come.": "Käufer, die Abholung wählen, erfahren nicht, wann sie kommen können.",
 "Buyers who did not ask for news. They get emails about what they bought, never one you send to your list.": "Käufer, die keine Neuigkeiten wollten. Sie bekommen E-Mails zu ihrem Kauf, nie eine, die du an deine Liste sendest.",
 "Buyers who did not ask, as contacts only": "Käufer ohne Zustimmung, nur als Kontakte",
 "Buyers who did not ask, as profiles only": "Käufer ohne Zustimmung, nur als Profile",
 "Buyers won't be able to check out yet": "Käufer können noch nicht bezahlen",
 "Buyers write to it about their orders. The same address your receipts show.": "Käufer schreiben dorthin zu ihren Bestellungen. Dieselbe Adresse wie auf deinen Belegen.",
