 "Download unfulfilled orders as a CSV for a warehouse or a spreadsheet.": "Lade unerledigte Bestellungen als CSV für ein Lager oder eine Tabelle herunter.",
 "Downloads and courses: days after purchase": "Downloads und Kurse: Tage nach dem Kauf",
 "Downloads, courses and memberships. In the EU, VAT on digital sales is charged at the rate of the buyer's country, so add a region for each country you sell to.": "Downloads, Kurse und Mitgliedschaften. In der EU wird die MwSt. auf digitale Verkäufe zum Satz des Käuferlandes berechnet, also leg für jedes Land, in das du verkaufst, eine Region an.",
 "Draft": "Entwurf",
