 "Importing": "Wird importiert",
 "Improved loading skeleton structures for Explore, Analytics, and Upgrade pages to better match actual page layouts.": "Die Lade-Platzhalter für Entdecken, Analysen und Upgrade entsprechen jetzt besser den echten Seiten.",
 "Improved settings page with smoother sticky save bar animations, toast notifications, and faster tab navigation with skeleton loading.": "Einstellungen mit flüssigerer Speicherleiste, Hinweisen und schnellerem Tab-Wechsel mit Lade-Platzhaltern.",
 "Improvement": "Verbesserung",
 "In 17TRACK, Settings > Webhook: add this address. 17TRACK signs updates with your API key. Without it Storelib checks every few hours.": "In 17TRACK unter Settings > Webhook: Füg diese Adresse hinzu. 17TRACK signiert Updates mit deinem API-Schlüssel. Ohne das prüft Storelib alle paar Stunden.",
 "In AfterShip, Settings > Webhooks: add this address, then paste its webhook secret under Change key, so updates arrive the moment they happen. Without it Storelib checks every few hours.": "In AfterShip unter Settings > Webhooks: Füg diese Adresse hinzu und füge dann ihr Webhook-Secret unter „Schlüssel ändern“ ein, damit Updates sofort ankommen. Ohne das prüft Storelib alle paar Stunden.",
 "In Gelato, Developer › Webhooks, add this address for order status and tracking code updates:": "Füg in Gelato unter Developer › Webhooks diese Adresse für Bestellstatus und Sendungsnummern hinzu:",
 "In Google Analytics, Reports › Realtime shows a visit within a minute. The “Data collection isn't active” notice on your stream can take up to 48 hours to go away.": "In Google Analytics zeigt Berichte › Echtzeit einen Besuch innerhalb einer Minute. Der Hinweis „Datenerfassung ist nicht aktiv“ in deinem Stream kann bis zu 48 Stunden bleiben.",
