 "Invite people by email. They get a link, sign in with their own Storelib account, and open your store from their dashboard.": "Lade Leute per E-Mail ein. Sie bekommen einen Link, melden sich mit ihrem eigenen Storelib-Konto an und öffnen deinen Shop aus ihrem Dashboard.",
