 "Is there a refund policy?": "Gibt es eine Erstattungsrichtlinie?",
 "Issued once DNS is set": "Wird ausgestellt, sobald DNS steht",
 "It appears here": "Es erscheint hier",
 "It applies only to products in these collections.": "Gilt nur für Produkte in diesen Kollektionen.",
 "It applies right away.": "Das gilt sofort.",
 "It arrived damaged": "Es kam beschädigt an",
 "It came in {when}. {amount} so far.": "Er kam {when}. Bisher {amount}.",
 "It comes off your page and cannot be brought back.": "Es verschwindet von deiner Seite und lässt sich nicht zurückholen.",
 "It comes off your page. If it has sales it is archived instead, so buyers keep their access.": "Es verschwindet von deiner Seite. Hat es Verkäufe, wird es archiviert, damit Käufer ihren Zugang behalten.",
 "It could not be published. Try again.": "Konnte nicht veröffentlicht werden. Versuch es noch mal.",
 "It disappears for everyone. Orders and payments are kept. Not possible while members still pay for it.": "Sie verschwindet für alle. Bestellungen und Zahlungen bleiben erhalten. Nicht möglich, solange Mitglieder dafür zahlen.",
 "It goes back to their card in 5 to 10 business days, and your share comes back from your Stripe balance. They get an email.": "Das Geld geht in 5 bis 10 Werktagen zurück auf die Karte, dein Anteil kommt aus deinem Stripe-Guthaben. Die Person bekommt eine E-Mail.",
 "It goes live at": "Geht live auf",
 "It goes live at {site}.": "Sie geht unter {site} live.",
 "It happened {when}, across {count, plural, one {# sale} other {# sales}}.": "Es passierte {when}, über {count, plural, one {# Verkauf} other {# Verkäufe}}.",
 "It has not been saved yet, so it will not be kept.": "Er wurde noch nicht gespeichert und wird daher nicht behalten.",
 "It has not been saved yet, so nothing you added will be kept.": "Es wurde noch nicht gespeichert, also bleibt nichts von dem, was du hinzugefügt hast.",
 "It has sales, so it will be archived, not deleted. It comes off your page and buyers keep their access.": "Es hat Verkäufe, also wird es archiviert statt gelöscht. Es verschwindet von deiner Seite, und Käufer behalten ihren Zugang.",
 "It has to end after it starts.": "Es muss nach dem Beginn enden.",
 "It hasn't arrived": "Es ist nicht angekommen",
 "It hides before it shows, so it would never be on the page.": "Es wird ausgeblendet, bevor es erscheint, wäre also nie auf der Seite.",
 "It is a draft. Only you can see it until you publish.": "Sie ist ein Entwurf. Bis zur Veröffentlichung siehst nur du sie.",
 "It is gone for good, with its photos. To take it off your store and keep it, hide it instead.": "Sie ist für immer weg, mit ihren Fotos. Um sie aus dem Shop zu nehmen und zu behalten, blende sie stattdessen aus.",
 "It is hidden from your product page and its rating now. Storelib reads it and either brings it back or keeps it hidden.": "Sie ist jetzt auf deiner Produktseite und in der Bewertung ausgeblendet. Storelib liest sie und bringt sie zurück oder lässt sie ausgeblendet.",
 "It is not a Storelib product and is not listed anywhere else.": "Es ist kein Storelib-Produkt und wird nirgendwo sonst gelistet.",
 "It is not connected yet, so nothing stops working.": "Sie ist noch nicht verbunden, also hört nichts auf zu funktionieren.",
 "It is off until you turn it on.": "Sie ist aus, bis du sie einschaltest.",
 "It is removed from Messages. The email you got about it stays in your inbox, and the sender stays in your contacts.": "Sie wird aus den Nachrichten entfernt. Die E-Mail dazu bleibt in deinem Postfach und der Absender in deinen Kontakten.",
 "It is removed with its numbers. Anything already sent stays in people's inboxes.": "Sie wird mit ihren Zahlen entfernt. Bereits Gesendetes bleibt in den Postfächern.",
 "It is yours": "Es gehört dir",
 "It may have been deleted. Go back to your websites.": "Sie wurde vielleicht gelöscht. Geh zurück zu deinen Websites.",
 "It opens soon": "Öffnet bald",
 "It plays on your page in the YouTube or Vimeo player.": "Es läuft auf deiner Seite im YouTube- oder Vimeo-Player.",
 "It replaces “{name}” at": "Ersetzt „{name}“ auf",
 "It replaces “{name}” at {site}. Nothing is deleted.": "Sie ersetzt „{name}“ unter {site}. Nichts wird gelöscht.",
 "It shows as cancelled to members, and anyone going hears about it. You can put it back on.": "Es wird Mitgliedern als abgesagt angezeigt und alle Teilnehmer erfahren davon. Du kannst es wieder ansetzen.",
 "It starts as a draft. Add its lessons, then publish it.": "Es startet als Entwurf. Füg Lektionen hinzu und veröffentliche es dann.",
 "It stops at once for everyone partway through, and its history goes with it.": "Sie stoppt sofort für alle, die mittendrin sind, und ihr Verlauf verschwindet mit ihr.",
 "It takes nothing off downloads or courses in the same cart.": "Zieht nichts von Downloads oder Kursen im selben Warenkorb ab.",
 "It usually arrives in 1 to 3 business days.": "Das dauert meist 1 bis 3 Werktage.",
 "It was already sent to your print partner. Cancel it there too.": "Sie wurde schon an deinen Druckpartner geschickt. Storniere sie dort auch.",
 "It was archived instead": "Es wurde stattdessen archiviert",
 "It was deleted. The email you got about it is still in your inbox.": "Sie wurde gelöscht. Die E-Mail dazu ist noch in deinem Postfach.",
 "It was used, or it's past the return window.": "Es wurde benutzt oder die Rückgabefrist ist vorbei.",
 "It's a passport": "Es ist ein Pass",
 "It's here": "Es ist da",
 "It's kept as a draft, so the title and photos can wait. You come back to it here.": "Es wird als Entwurf gespeichert, Titel und Fotos können also warten. Du findest es hier wieder.",
