 "Member status": "Mitgliedsstatus",
 "Members": "Mitglieder",
 "Members are told about announcements.": "Mitglieder werden über Ankündigungen informiert.",
 "Members can comment on posts here.": "Mitglieder können hier Beiträge kommentieren.",
 "Members can read it; nobody can post. Bringing it back makes it a draft.": "Mitglieder können sie lesen; niemand kann posten. Zurückholen macht sie zum Entwurf.",
 "Members can see who else is here.": "Mitglieder sehen, wer noch hier ist.",
 "Members can still read it. Nobody can post or join until you bring it back. Nothing is deleted.": "Mitglieder können sie weiter lesen. Niemand kann posten oder beitreten, bis du sie zurückholst. Nichts wird gelöscht.",
 "Members earn points when their posts and comments get reactions, and climb levels. A leaderboard shows in the community.": "Mitglieder sammeln Punkte, wenn ihre Beiträge und Kommentare Reaktionen bekommen, und steigen im Level auf. In der Community gibt es eine Bestenliste.",
 "Members get these in their library while their membership lasts.": "Mitglieder haben sie in ihrer Bibliothek, solange die Mitgliedschaft läuft.",
 "Members now": "Mitglieder jetzt",
 "Members on {name}": "Mitglieder bei {name}",
 "Members pay for a tier to join.": "Mitglieder zahlen für eine Stufe, um beizutreten.",
 "Members pay monthly or yearly to join your community.": "Mitglieder zahlen monatlich oder jährlich, um deiner Community beizutreten.",
 "Members pay once, in a checkout inside the community. ": "Mitglieder zahlen einmal, in einem Checkout in der Community. ",
 "Members pay once, in a checkout inside the community. The meeting link, the address and who else is going open when they have a ticket.": "Mitglieder zahlen einmal, in einem Checkout in der Community. Meeting-Link, Adresse und wer noch kommt, sehen sie mit Ticket.",
 "Members pay through Stripe. You can add a yearly price or more tiers later.": "Mitglieder zahlen über Stripe. Einen Jahrespreis oder weitere Stufen kannst du später hinzufügen.",
 "Members pay to join, every month, every year or once.": "Mitglieder zahlen für den Beitritt, monatlich, jährlich oder einmalig.",
 "Members pay you through Stripe. Nobody can join a paid community until payouts are connected.": "Mitglieder zahlen dich über Stripe. Niemand kann einer bezahlten Community beitreten, bis Auszahlungen verbunden sind.",
 "Members pay {amount} once, in a checkout inside the community. ": "Mitglieder zahlen einmal {amount}, in einem Checkout in der Community. ",
 "Members pay {priceText}.": "Mitglieder zahlen {priceText}.",
 "Members paying now, including anyone whose card is being retried. Somebody who cancelled keeps access until their period ends and is not counted.": "Mitglieder, die gerade zahlen, auch solche, deren Karte erneut belastet wird. Wer gekündigt hat, behält den Zugang bis zum Periodenende und wird nicht gezählt.",
 "Members post": "Mitglieder posten",
 "Members reach levels by taking part. Below it, they see the program with the level it opens at.": "Mitglieder erreichen Level durch Mitmachen. Darunter sehen sie das Programm mit dem Level, ab dem es öffnet.",
 "Members see it under Learn.": "Mitglieder sehen es unter Lernen.",
 "Members see posts on their membership page. Put the membership on sale in Settings to let people join.": "Mitglieder sehen Beiträge auf ihrer Mitgliedschaftsseite. Stell die Mitgliedschaft in den Einstellungen in den Verkauf, damit Leute beitreten können.",
 "Members see them before they join and when they post.": "Mitglieder sehen sie vor dem Beitritt und beim Posten.",
 "Members stop seeing it here. The course and its buyers are not touched.": "Mitglieder sehen ihn hier nicht mehr. Kurs und Käufer bleiben unberührt.",
 "Members stop seeing it in the classroom. The course and its buyers are not touched.": "Mitglieder sehen ihn nicht mehr im Klassenzimmer. Kurs und Käufer bleiben unberührt.",
 "Members stop seeing it, and every open report about it is closed. You can restore it from the Feed.": "Mitglieder sehen es nicht mehr, und alle offenen Meldungen dazu werden geschlossen. Du kannst es im Feed wiederherstellen.",
 "Members stop seeing it. You can restore it from Removed.": "Mitglieder sehen ihn nicht mehr. Du kannst ihn unter Entfernt wiederherstellen.",
 "Members who could attend can watch it on the event page afterwards.": "Mitglieder, die teilnehmen konnten, können sie danach auf der Event-Seite ansehen.",
 "Members who have it lose it.": "Mitglieder, die es haben, verlieren es.",
 "Members write to you from the community. Messages reach your inbox and this email; it stays private unless you show it.": "Mitglieder schreiben dir aus der Community. Nachrichten landen in deinem Posteingang und bei dieser E-Mail; sie bleibt privat, außer du zeigst sie.",
