 "Of the people who visited, how many opened a product, how many started a checkout, and how many orders came in. Each step is shown as a share of the one before.": "Von den Besuchern: wie viele ein Produkt geöffnet, wie viele einen Checkout begonnen haben und wie viele Bestellungen eingingen. Jeder Schritt wird als Anteil des vorherigen gezeigt.",
