 "On any post or comment by a member ranked below them.": "Bei jedem Beitrag oder Kommentar eines rangniedrigeren Mitglieds.",
 "On every page: your website, your storelib.com page and products, your OnePage, checkout and the thank you page, with product views, add to cart, checkout and purchases.": "Auf jeder Seite: deine Website, deine storelib.com-Seite und Produkte, deine OnePage, der Checkout und die Danke-Seite, mit Produktaufrufen, In-den-Warenkorb, Checkout und Käufen.",
