 "Onboarding reminders": "Einstiegs-Erinnerungen",
 "Once it has passed, say": "Danach anzeigen",
 "Once it is available you can cash it out, and it usually reaches your bank in 1 to 3 business days.": "Sobald es verfügbar ist, kannst du es auszahlen; es kommt meist in 1 bis 3 Werktagen bei deiner Bank an.",
 "Once it starts it cannot be taken back. You can stop the ones not yet sent.": "Einmal gestartet, lässt es sich nicht zurücknehmen. Du kannst die noch nicht gesendeten stoppen.",
 "Once per person": "Einmal pro Person",
 "Once saved, they'll appear on your OnePage.": "Nach dem Speichern erscheinen sie auf deiner OnePage.",
 "Once the items are back, mark them received: you choose whether they go back into stock, and you refund the buyer from the same screen.": "Sind die Artikel zurück, markier sie als erhalten: Du wählst, ob sie zurück in den Bestand gehen, und erstattest dem Käufer im selben Bildschirm.",
 "One a line, for example\nfree followers\ncrypto signal*": "Eins pro Zeile, zum Beispiel\ngratis Follower\nkrypto signal*",
 "One email a day at most, listing what sold down to its low stock line.": "Höchstens eine E-Mail pro Tag mit allem, was bis zur Grenze verkauft wurde.",
 "One email an hour later with a link back to what they chose, only to buyers who ticked the news box. It stops the moment they buy.": "Eine E-Mail eine Stunde später mit einem Link zu ihrer Auswahl, nur an Käufer mit angehaktem Newsletter-Feld. Stoppt, sobald sie kaufen.",
 "One email an hour later, only to buyers who ticked the news box. With the news box hidden nobody can tick it, so no reminder goes out.": "Eine E-Mail eine Stunde später, nur an Käufer mit angehaktem Newsletter-Feld. Ist das Feld ausgeblendet, kann es niemand anhaken, also geht keine Erinnerung raus.",
 "One event has a price, and nobody can buy a ticket until payouts are connected.": "Ein Event hat einen Preis, und niemand kann ein Ticket kaufen, bis Auszahlungen verbunden sind.",
 "One event has a ticket price, but payouts are not connected, so nobody can buy it.": "Ein Event hat einen Ticketpreis, aber Auszahlungen sind nicht verbunden, also kann niemand kaufen.",
