 "Store details need their database update (SQL part 109). Until it runs, what you see here is not saved.": "Shop-Angaben brauchen ihr Datenbank-Update (SQL-Teil 109). Bis dahin wird hier nichts gespeichert.",
 "Store is unpublished. Go to Settings to publish.": "Der Shop ist nicht veröffentlicht. Geh zu Einstellungen, um ihn zu veröffentlichen.",
 "Store name": "Shopname",
