 "Stored encrypted and never shown again.": "Verschlüsselt gespeichert und nie wieder angezeigt.",
 "Storelib AI": "Storelib AI",
 "Storelib AI could not be reached. Check your connection and try again.": "Storelib AI war nicht erreichbar. Prüf deine Verbindung und versuch es noch mal.",
 "Storelib AI is already included in your plan. If you would rather it ran on your own OpenAI key, connect it here and those edits stop counting against your plan's AI edits.": "Storelib AI ist bereits in deinem Plan enthalten. Wenn es lieber mit deinem eigenen OpenAI-Schlüssel laufen soll, verbinde ihn hier, dann zählen diese Änderungen nicht mehr zu den KI-Änderungen deines Plans.",
 "Storelib AI is busy right now. Try again in a moment.": "Storelib AI ist gerade beschäftigt. Versuch es gleich noch mal.",
 "Storelib AI now answers on your account. Your key is used for your chats only, kept encrypted, and never shown again.": "Storelib AI antwortet jetzt über dein Konto. Dein Schlüssel wird nur für deine Chats genutzt, verschlüsselt gespeichert und nie wieder angezeigt.",
 "Storelib AI reads these before every change on every one of your websites. Tell it “remember this” in the builder, or add one here.": "Storelib AI liest das vor jeder Änderung auf all deinen Websites. Sag im Editor „merk dir das“ oder füg es hier hinzu.",
 "Storelib Help Center": "Storelib-Hilfecenter",
 "Storelib Payments": "Storelib Payments",
 "Storelib Reviews is on": "Storelib Reviews ist an",
 "Storelib Reviews needs its database update (SQL part 134). Until it runs, nothing here is kept.": "Storelib Reviews braucht sein Datenbank-Update (SQL-Teil 134). Bis dahin wird hier nichts gespeichert.",
 "Storelib address": "Storelib-Adresse",
 "Storelib adds the package's empty weight to the products inside when it works out a weight based shipping rate, so the buyer pays for what the parcel really weighs.": "Storelib addiert das Leergewicht des Pakets zu den Produkten, wenn es einen Gewichtstarif berechnet, damit der Käufer für das echte Paketgewicht zahlt.",
 "Storelib apps": "Storelib-Apps",
 "Storelib apps and the services you already use.": "Storelib-Apps und die Dienste, die du schon nutzt.",
 "Storelib badge hidden": "Storelib-Abzeichen ausgeblendet",
 "Storelib badge shown": "Storelib-Abzeichen sichtbar",
 "Storelib can't reach your repository": "Storelib erreicht dein Repository nicht",
 "Storelib cannot see any repositories. Give it access to one on GitHub, then": "Storelib sieht keine Repositorys. Gib ihm auf GitHub Zugriff auf eins und dann",
 "Storelib charges what you set and nothing more. Ask an accountant which rates apply to you.": "Storelib berechnet, was du festlegst, und sonst nichts. Frag eine Steuerberatung, welche Sätze für dich gelten.",
 "Storelib charges what you set here and nothing more. Check which rates apply to you with an accountant.": "Storelib berechnet, was du hier festlegst, und nichts weiter. Kläre mit einer Steuerberatung, welche Sätze für dich gelten.",
 "Storelib couldn't open your site to take the push": "Storelib konnte deine Website nicht öffnen, um den Push zu übernehmen",
 "Storelib couldn't sign in to your repository. Reconnect GitHub and try again. Nothing on your site was lost.": "Storelib konnte sich nicht in deinem Repository anmelden. Verbinde GitHub neu und versuch es erneut. Auf deiner Website ging nichts verloren.",
 "Storelib didn't answer": "Storelib hat nicht geantwortet",
 "Storelib fee": "Storelib-Gebühr",
 "Storelib includes it in the answer to the bank.": "Storelib nimmt es in die Antwort an die Bank auf.",
 "Storelib is answering the bank. Add anything that proves the sale so it can be sent with the response.": "Storelib antwortet der Bank. Füge alles hinzu, was den Verkauf belegt, damit es mitgeschickt wird.",
 "Storelib is helping with this case. Its messages go to you and the buyer.": "Storelib hilft bei diesem Fall. Die Nachrichten gehen an dich und den Käufer.",
 "Storelib is not allowed to use the microphone. Allow Microphone in Storelib's app permissions, then try again.": "Storelib darf das Mikrofon nicht nutzen. Erlaube das Mikrofon in den App-Berechtigungen von Storelib und versuch es erneut.",
 "Storelib is not allowed to use the microphone. Turn on Microphone for Storelib in Settings, then try again.": "Storelib darf das Mikrofon nicht nutzen. Schalte Mikrofon für Storelib in den Einstellungen ein und versuch es erneut.",
 "Storelib news": "Storelib-Neuigkeiten",
