 "Storelib support": "Storelib-Support",
 "Storelib suspended this community. Members cannot open it. Contact support to talk about it.": "Storelib hat diese Community gesperrt. Mitglieder können sie nicht öffnen. Wende dich an den Support, um darüber zu sprechen.",
 "Storelib took this community out of Explore. Contact support to talk about it.": "Storelib hat diese Community aus Entdecken genommen. Wende dich an den Support, um darüber zu sprechen.",
 "Storelib will look at the case and write to you both.": "Storelib sieht sich den Fall an und schreibt euch beiden.",
 "Storelib writes this website's whole theme into it: settings, pages, header and footer, sections and blocks, with an AGENTS.md your tool reads first.": "Storelib schreibt das ganze Theme dieser Website hinein: Einstellungen, Seiten, Kopf- und Fußbereich, Abschnitte und Blöcke, mit einer AGENTS.md, die dein Tool zuerst liest.",
 "Storelib's fee for your plan ({freeFee} on Free, {proFee} on Pro), and Stripe's card processing fee, which Stripe charges on every plan. There is nothing else.": "Die Storelib-Gebühr deines Plans ({freeFee} bei Free, {proFee} bei Pro) und Stripes Kartengebühr, die Stripe in jedem Plan berechnet. Sonst nichts.",
 "Storelib, automatically": "Storelib, automatisch",
