 "They are off for now. You can turn them on in": "Sie sind gerade aus. Du kannst sie einschalten unter",
 "They are real starter projects rather than presets, and they come after the editor. Start blank or with AI for now.": "Es sind echte Startprojekte statt Voreinstellungen, und sie kommen nach dem Editor. Starte vorerst leer oder mit KI.",
 "They are removed from your files, and anything that still shows one of them will show nothing.": "Sie werden aus deinen Dateien entfernt, und alles, was noch eine davon zeigt, zeigt dann nichts.",
 "They are unsubscribed and get no more of your emails.": "Sie werden abgemeldet und bekommen keine E-Mails mehr von dir.",
 "They can ask again later.": "Die Person kann später erneut fragen.",
 "They can open the community and post again, and keep their points, level and posts.{free}": "Die Person kann die Community wieder öffnen und posten und behält Punkte, Level und Beiträge.{free}",
 "They can read everything but cannot post, comment, react or chat until it ends.": "Die Person kann alles lesen, aber bis zum Ende nicht posten, kommentieren, reagieren oder chatten.",
 "They can't open your store any more.": "Die Person kann deinen Shop nicht mehr öffnen.",
 "They can't place an order until they click the link we email them when they sign up. Turns on sign in as well.": "Sie können erst bestellen, wenn sie auf den Link in der Anmelde-E-Mail klicken. Schaltet auch die Anmeldung ein.",
 "They get access again now, and keep their points, level and posts.{free}": "Die Person hat jetzt wieder Zugang und behält Punkte, Level und Beiträge.{free}",
 "They get in without paying, and they are told what the ticket would have cost.": "Sie kommen ohne zu zahlen rein und erfahren, was das Ticket gekostet hätte.",
 "They get this tier without paying, until you end it.": "Die Person bekommt diese Stufe ohne Bezahlung, bis du es beendest.",
 "They have {points} now. ": "Hat jetzt {points}. ",
 "They hold the stock and ship it.": "Er hält den Bestand und versendet.",
 "They join as {role}: {value}. They sign in with their own Storelib account.": "Die Person kommt als {role} dazu: {value}. Sie meldet sich mit ihrem eigenen Storelib-Konto an.",
 "They lose access and cannot join again unless you unban them.": "Die Person verliert den Zugang und kann nicht wieder beitreten, außer du hebst den Bann auf.",
 "They lose access now and can join again. A paid membership keeps billing until they cancel it.": "Die Person verliert jetzt den Zugang und kann wieder beitreten. Eine bezahlte Mitgliedschaft läuft weiter, bis sie gekündigt wird.",
 "They lose access until you bring them back. Their posts stay.": "Die Person verliert den Zugang, bis du sie zurückholst. Ihre Beiträge bleiben.",
 "They pick a reason from your list and the items. You get an email and approve or decline it from the order.": "Er wählt einen Grund aus deiner Liste und die Artikel. Du bekommst eine E-Mail und gibst in der Bestellung frei oder lehnst ab.",
 "They're already on your team.": "Die Person ist schon in deinem Team.",
 "They're saved in your draft.": "Sie sind in deinem Entwurf gespeichert.",
 "Things you ship: clothing, prints, merch, gear, with stock.": "Dinge, die du versendest: Kleidung, Drucke, Merch, Ausrüstung, mit Bestand.",
 "This": "Das",
 "This Supabase account has no projects yet. Make one at supabase.com, then connect again.": "Dieses Supabase-Konto hat noch keine Projekte. Erstelle eins auf supabase.com und verbinde dann erneut.",
 "This account can't accept payments. Write to support@storelib.com and we'll help.": "Dieses Konto kann keine Zahlungen annehmen. Schreib an support@storelib.com, wir helfen dir.",
 "This action cannot be undone": "Das lässt sich nicht rückgängig machen",
 "This answer cannot be reported yet.": "Diese Antwort kann noch nicht gemeldet werden.",
 "This answer is no longer in your history.": "Diese Antwort ist nicht mehr in deinem Verlauf.",
 "This browser cannot record. Type it, or try another browser.": "Dieser Browser kann nicht aufnehmen. Tipp es oder nutz einen anderen Browser.",
 "This browser cannot show notifications.": "Dieser Browser kann keine Benachrichtigungen anzeigen.",
 "This browser could not shrink the picture.": "Dieser Browser konnte das Bild nicht verkleinern.",
 "This chat could not be loaded.": "Dieser Chat konnte nicht geladen werden.",
 "This check looks at the email before it, and there is none.": "Diese Prüfung schaut auf die E-Mail davor, und es gibt keine.",
 "This community is archived. Bring it back to change it.": "Diese Community ist archiviert. Hol sie zurück, um sie zu ändern.",
 "This community is archived. Members can read it, nobody can post. Bring it back from Settings.": "Diese Community ist archiviert. Mitglieder können lesen, niemand kann posten. Hol sie in den Einstellungen zurück.",
 "This course's modules and lessons are edited in the course itself, and change here too.": "Module und Lektionen dieses Kurses werden im Kurs selbst bearbeitet und ändern sich auch hier.",
 "This device": "Dieses Gerät",
 "This email appears on customer receipts and order confirmations. Customers write to it for support.": "Diese E-Mail steht auf Belegen und Bestellbestätigungen. Kunden schreiben dorthin, wenn sie Hilfe brauchen.",
 "This email cannot be sent yet.": "Diese E-Mail kann noch nicht gesendet werden.",
