 "This email, as your subscribers get it, to your own address.": "Diese E-Mail, wie deine Abonnenten sie bekommen, an deine eigene Adresse.",
 "This event is cancelled and nobody has had their money back yet. Refund each ticket below, or ask the owner to.": "Dieses Event ist abgesagt und noch niemand hat sein Geld zurück. Erstatte jedes Ticket unten oder bitte den Inhaber darum.",
