 "This gradient was written by hand in a form this control cannot read. It is kept as it is; changing anything below replaces it.": "Dieser Verlauf wurde von Hand in einer Form geschrieben, die dieses Feld nicht lesen kann. Er bleibt, wie er ist; jede Änderung unten ersetzt ihn.",
 "This is not a link to a video file. It should end in .mp4, .webm or .mov.": "Das ist kein Link zu einer Videodatei. Er sollte auf .mp4, .webm oder .mov enden.",
