 "This period has more activity than one report reads at once. Choose a shorter period for exact figures.": "Dieser Zeitraum hat mehr Aktivität, als ein Bericht auf einmal liest. Wähle einen kürzeren Zeitraum für genaue Zahlen.",
 "This photo, chosen": "Dieses Foto, gewählt",
 "This product": "Dieses Produkt",
 "This product has its own answer. Your other products keep the store setting.": "Dieses Produkt hat eine eigene Einstellung. Deine anderen Produkte behalten die Shop-Einstellung.",
 "This product is live. Save your changes before you go, or leave without them.": "Dieses Produkt ist live. Speichere deine Änderungen, bevor du gehst, oder geh ohne sie.",
 "This product is shipped": "Dieses Produkt wird versendet",
 "This product's stock at the CJ location follows CJ's warehouses, read every six hours and when CJ says it changed.": "Der Bestand dieses Produkts am CJ-Standort folgt den CJ-Lagern, alle sechs Stunden gelesen und wenn CJ eine Änderung meldet.",
 "This program is for members.": "Dieses Programm ist für Mitglieder.",
 "This program is for {label}.": "Dieses Programm ist für {label}.",
 "This program is for {value} of the community.": "Dieses Programm ist für {value} der Community.",
 "This program is for {value}{value2}.": "Dieses Programm ist für {value}{value2}.",
 "This program is sold on its own. Buy it once and it stays in your Learn for as long as you are a member.": "Dieses Programm wird einzeln verkauft. Kauf es einmal, dann bleibt es in deinem Lernen, solange du Mitglied bist.",
 "This program opens at {value}. Levels come from taking part in the community.": "Dieses Programm öffnet bei {value}. Level bekommt man durch Mitmachen in der Community.",
 "This publish will not be backed up. Run supabase/sql/RUN_THEME_BACKUPS.sql once to turn backups on.": "Diese Veröffentlichung wird nicht gesichert. Führ einmal supabase/sql/RUN_THEME_BACKUPS.sql aus, um Backups einzuschalten.",
 "This replaces {domain}. For 30 days {domain2} sends its visitors on to {clean}, then it stops. Press Replace to go ahead.": "Das ersetzt {domain}. 30 Tage lang leitet {domain2} Besucher zu {clean} weiter, danach endet es. Drück „Ersetzen“, um fortzufahren.",
 "This sale cannot be refunded.": "Dieser Verkauf kann nicht erstattet werden.",
