 "This setting takes a {what}.": "Diese Einstellung braucht ein(e) {what}.",
 "This site follows {value}. Merge it into {value2} on GitHub to bring it in.": "Diese Website folgt {value}. Merge es auf GitHub in {value2}, um es zu übernehmen.",
 "This site uses its own copy of this built-in section. Other sites keep Storelib's.": "Diese Website nutzt eine eigene Kopie dieses integrierten Abschnitts. Andere Websites behalten die von Storelib.",
 "This text": "Dieser Text",
