 "This text appears on your customers' bank statements. It helps them identify the charge. Format: \"(Your Name) - STORELIB\". Only your name can be changed. Max 22 characters total.": "Dieser Text erscheint auf den Kontoauszügen deiner Kunden und hilft ihnen, die Abbuchung zu erkennen. Format: „(Dein Name) - STORELIB“. Nur dein Name lässt sich ändern. Insgesamt höchstens 22 Zeichen.",
