 "To count stock, have it fulfilled from one of your own locations.": "Um Bestand zu zählen, lass es von einem deiner Standorte ausführen.",
 "To days": "Bis (Tage)",
 "To do": "Offen",
 "To keep your payouts going, Stripe asks for this now{value}. It takes a minute.": "Damit deine Auszahlungen weiterlaufen, fragt Stripe jetzt danach{value}. Dauert eine Minute.",
 "To move a photo or video, press Space or Enter on it, then the arrow keys. Press Space or Enter again to drop it, or Escape to put it back. The first is the thumbnail.": "Um ein Foto oder Video zu verschieben, drück Leertaste oder Enter darauf, dann die Pfeiltasten. Drück erneut Leertaste oder Enter zum Ablegen oder Escape zum Zurücklegen. Das erste ist das Vorschaubild.",
 "To move a question, press Space or Enter on its handle, then the up and down arrow keys. Press Space or Enter again to drop it, or Escape to put it back.": "Um eine Frage zu verschieben, drück Leertaste oder Enter auf ihrem Griff, dann die Pfeiltasten hoch und runter. Drück erneut Leertaste oder Enter zum Ablegen oder Escape zum Zurücklegen.",
 "To move an option, press Space on its handle, then the up and down arrow keys, then Space again.": "Um eine Option zu verschieben, drück Leertaste am Griff, dann die Pfeiltasten hoch und runter, dann wieder Leertaste.",
 "To send a product here: in the product, choose Print on demand and the {value} location, and give each variant the same SKU it has in {name}.": "Um ein Produkt hierher zu senden: Wähl im Produkt Print on Demand und den Standort {value} und gib jeder Variante dieselbe SKU wie in {name}.",
 "To send a product here: in the product, choose {value} and the {value2} location, then match each variant to {name}'s below.": "Um ein Produkt hierher zu senden: Wähl im Produkt {value} und den Standort {value2} und ordne dann jede Variante unten der von {name} zu.",
