 "What you hear about": "Worüber du informiert wirst",
 "What you pick when you refund an order. It stays on the order's timeline.": "Was du beim Erstatten einer Bestellung wählst. Es bleibt im Verlauf der Bestellung.",
 "What you will cover and who it is for": "Was du behandelst und für wen es ist",
 "What you wrote in this email is replaced.": "Was du in dieser E-Mail geschrieben hast, wird ersetzt.",
 "What your buyers get from you, and when. Open one to see it and change its words. Each goes out with your store's name, and a reply comes to your contact email.": "Was deine Käufer von dir bekommen und wann. Öffne eine, um sie zu sehen und den Text zu ändern. Jede geht mit deinem Shopnamen raus, Antworten kommen an deine Kontakt-E-Mail.",
 "What your completed sales took in over this period, before fees and refunds.": "Was deine abgeschlossenen Verkäufe in diesem Zeitraum eingebracht haben, vor Gebühren und Erstattungen.",
