 "When": "Wann",
 "When a buyer asks to return items, so they know it arrived.": "Wenn ein Käufer eine Rücksendung anfragt, damit er weiß, dass sie angekommen ist.",
 "When a buyer has a problem with an order (it hasn't arrived, it came damaged, they want a refund), they ask from their order page and it lands here and in your email. You answer first; either of you can ask Storelib to step in.": "Wenn ein Käufer ein Problem mit einer Bestellung hat (nicht angekommen, beschädigt, Erstattung gewünscht), fragt er über seine Bestellseite, und es landet hier und in deinem Postfach. Du antwortest zuerst; jeder von euch kann Storelib bitten einzugreifen.",
 "When a draft was last changed.": "Wann ein Entwurf zuletzt geändert wurde.",
 "When a review comes in": "Wenn eine Bewertung eingeht",
 "When a shipment is marked as failed: the carrier, or your own delivery, couldn't deliver it.": "Wenn eine Sendung als fehlgeschlagen markiert ist: Der Versanddienst oder deine eigene Lieferung konnte nicht zustellen.",
 "When a store's owner invites you, it shows here and you can open it from your own account.": "Wenn dich ein Shop-Inhaber einlädt, erscheint der Shop hier und du kannst ihn von deinem Konto aus öffnen.",
 "When buyers can come. Shown at checkout and in the pickup email.": "Wann Käufer kommen können. Im Checkout und in der Abhol-E-Mail angezeigt.",
 "When does Pro pay for itself?": "Wann rechnet sich Pro?",
 "When it pushes to": "Wenn es pusht nach",
 "When it pushes to {branch}, the change shows here as a draft within seconds.": "Wenn er nach {branch} pusht, erscheint die Änderung hier in Sekunden als Entwurf.",
 "When it's marked delivered.": "Wenn es als zugestellt markiert ist.",
 "When members leave they can say why. Their answers show up here.": "Wenn Mitglieder gehen, können sie sagen, warum. Ihre Antworten erscheinen hier.",
 "When members report a post, a comment or somebody, it lands here.": "Wenn Mitglieder einen Beitrag, einen Kommentar oder jemanden melden, landet es hier.",
 "When pressed": "Beim Drücken",
 "When returns are on, a buyer sees Request a return on their order page for as many days as your return window.": "Sind Rücksendungen an, sieht der Käufer auf seiner Bestellseite „Rücksendung anfragen“, so viele Tage wie deine Rückgabefrist.",
 "When somebody writes to you through the contact form on your website, the message shows here and in your email.": "Wenn dir jemand über das Kontaktformular deiner Website schreibt, erscheint die Nachricht hier und in deinem Postfach.",
 "When someone joins your list": "Wenn sich jemand in deine Liste einträgt",
 "When someone leaves checkout": "Wenn jemand den Checkout verlässt",
