 "When the items reach you.": "Wenn die Artikel bei dir ankommen.",
 "When the next scheduled email is sent.": "Wann die nächste geplante E-Mail gesendet wird.",
 "When the return is closed, with any refund.": "Wenn die Rücksendung abgeschlossen ist, mit etwaiger Erstattung.",
 "When visitors subscribe, they can download \"": "Wenn Besucher abonnieren, können sie „",
