 "You did not meet the federal threshold ($20,000 + 200 transactions). This draft summary is for your records. Ask a tax professional for filing guidance.": "Du hast die US-Bundesschwelle (20.000 $ und 200 Transaktionen) nicht erreicht. Diese Entwurfsübersicht ist für deine Unterlagen. Frag für die Steuererklärung eine Steuerberatung.",
 "You didn't meet the threshold. Download a draft summary for your tax professional.": "Du hast die Schwelle nicht erreicht. Lade eine Entwurfsübersicht für deine Steuerberatung herunter.",
