 "Your phone is shown to your payment provider and on order emails, so a buyer or a carrier can reach you about an order.": "Deine Telefonnummer sieht dein Zahlungsanbieter und sie steht in Bestell-E-Mails, damit Käufer oder Kuriere dich wegen einer Bestellung erreichen.",
