 "Your plan, invoices and payment card": "Dein Plan, Rechnungen und Zahlungskarte",
 "Your prices are in {baseCurrency}. Cards are charged in {chargeCurrency}. A market in another currency shows an estimate converted at the European Central Bank's rate, and says so before payment.": "Deine Preise sind in {baseCurrency}. Karten werden in {chargeCurrency} belastet. Ein Markt in anderer Währung zeigt eine Schätzung zum Kurs der Europäischen Zentralbank und weist vor der Zahlung darauf hin.",
