 "Your programs and lessons, inside the community.": "Deine Programme und Lektionen, in der Community.",
 "Your questions": "Deine Fragen",
 "Your rates go by weight, so without one they ship at the lightest price.": "Deine Tarife richten sich nach Gewicht, ohne Gewicht wird zum leichtesten Preis versendet.",
